const slides=[...document.querySelectorAll('.slide')];let current=0;const dots=document.querySelector('#dots');const overview=document.querySelector('#overview');const notes=document.querySelector('#notes');const counter=document.querySelector('#counter');
function scale(){if(innerWidth<=700){document.querySelector('#deck').style.transform='none';return}const s=Math.min(innerWidth/1600,(innerHeight-100)/900);document.querySelector('#deck').style.transform=`translate(-50%,-50%) scale(${s})`}
slides.forEach((s,i)=>{s.dataset.number=`${String(i+1).padStart(2,'0')} / ${slides.length}`;s.setAttribute('role','region');s.setAttribute('aria-label',`Slide ${i+1}: ${s.dataset.title}`);const b=document.createElement('button');b.setAttribute('aria-label',`Go to slide ${i+1}: ${s.dataset.title}`);b.title=s.dataset.title;b.onclick=()=>show(i);dots.append(b);const o=document.createElement('button');o.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${s.dataset.title}`;o.onclick=()=>{overview.close();show(i)};document.querySelector('#overviewGrid').append(o)});
function show(i){current=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,j)=>{s.classList.toggle('active',j===current);s.setAttribute('aria-hidden',j!==current);s.inert=j!==current});[...dots.children].forEach((d,j)=>{d.classList.toggle('active',j===current);d.setAttribute('aria-current',j===current?'step':'false')});[...document.querySelector('#overviewGrid').children].forEach((d,j)=>d.classList.toggle('current',j===current));counter.textContent=`${String(current+1).padStart(2,'0')} / ${slides.length}`;document.querySelector('.progress i').style.width=`${(current+1)/slides.length*100}%`;document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===slides.length-1;document.title=`${slides[current].dataset.title} · Rivane`;history.replaceState(null,'',`#${current+1}`);document.querySelector('#noteTitle').textContent=`${String(current+1).padStart(2,'0')} / ${slides[current].dataset.title}`;document.querySelector('#noteText').textContent=slides[current].dataset.note;window.scrollTo(0,0)}
document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);function toggleFull(){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>{})}document.querySelector('#full').onclick=toggleFull;document.querySelector('#overviewBtn').onclick=()=>overview.showModal();document.querySelector('#notesBtn').onclick=()=>notes.showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());document.addEventListener('keydown',e=>{if(overview.open||notes.open)return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);if(e.key.toLowerCase()==='o')overview.showModal();if(e.key.toLowerCase()==='n')notes.showModal();if(e.key.toLowerCase()==='f')toggleFull()});let touchX=0,touchY=0;document.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX;touchY=e.changedTouches[0].clientY},{passive:true});document.addEventListener('touchend',e=>{if(overview.open||notes.open)return;let dx=e.changedTouches[0].clientX-touchX,dy=e.changedTouches[0].clientY-touchY;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.5)show(current+(dx<0?1:-1))},{passive:true});addEventListener('resize',scale);addEventListener('hashchange',()=>show((parseInt(location.hash.slice(1))||1)-1));
const journey=[
{title:'An invoice arrives.',desc:'Rivane extracts the amount and service period from the source.',stage:'SOURCE RECEIVED',rows:['Source document','Invoice captured','Extracted amount','$12,000'],status:'Captured · Nothing posted'},
{title:'Rivane proposes a treatment.',desc:'The annual subscription is proposed as a prepaid expense, released monthly.',stage:'AI PROPOSAL',rows:['Suggested treatment','Prepaid expense','Monthly expense','$1,000 × 12'],status:'Proposed · Awaiting human approval'},
{title:'Finance makes the decision.',desc:'An authorized reviewer checks the source and approves the proposed treatment.',stage:'HUMAN APPROVAL',rows:['Reviewer','Authorized finance owner','Decision','Treatment approved'],status:'Approved · Execution authorized'},
{title:'The entry keeps its evidence.',desc:'The resulting record links back to the invoice, proposal and approval.',stage:'LINKED RECORD',rows:['Accounting record','Prepaid expense entry','Evidence','Source + approval linked'],status:'Recorded · Decision trace preserved'}
];let journeyIndex=0;let journeyPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;
const journeyButtons=[...document.querySelectorAll('[data-stage]')];
const play=document.querySelector('#journeyPlay');
function renderJourney(i){journeyIndex=i;const s=journey[i];document.querySelector('#journeyTitle').textContent=s.title;document.querySelector('#journeyDesc').textContent=s.desc;document.querySelector('#journeyStage').textContent=`STEP ${i+1} OF 4 · ${s.stage}`;document.querySelector('#journeyStatus').textContent=s.status;['journeyRowLabel','journeyRowValue','journeyRowLabel2','journeyRowValue2'].forEach((id,n)=>document.getElementById(id).textContent=s.rows[n]);journeyButtons.forEach((b,n)=>{b.classList.toggle('on',n===i);b.classList.toggle('done',n<i);if(n===i)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});play.textContent=journeyPaused?'Play':'Pause'}
let stageElapsed=0;let lastJourneyTime=performance.now();
journeyButtons.forEach((b,i)=>b.addEventListener('click',()=>{journeyPaused=true;stageElapsed=0;renderJourney(i)}));
play.addEventListener('click',()=>{journeyPaused=!journeyPaused;renderJourney(journeyIndex)});
function animateJourney(now){const delta=Math.min(now-lastJourneyTime,100);lastJourneyTime=now;if(current===0&&!document.hidden&&!journeyPaused){stageElapsed+=delta;if(stageElapsed>=6500){stageElapsed=0;renderJourney((journeyIndex+1)%journey.length)}}journeyButtons[journeyIndex].style.setProperty('--stage-progress',String(stageElapsed/6500));requestAnimationFrame(animateJourney)}
renderJourney(0);requestAnimationFrame(animateJourney);scale();show((parseInt(location.hash.slice(1))||1)-1);
